#!/usr/bin/env python3
"""Librarian trace pipeline.

Sweeps every Claude Code transcript on this machine, scrubs credential values,
verifies the staging copy is clean, and (only if something changed) pushes the
result to the public HF dataset crispwisp/wisp-claude-code-sessions.

Designed to be run unattended from a systemd timer. Never pushes if the scrub
verification fails. Originals under ~/.claude/projects are never modified.
"""
import os, re, sys, glob, json, shutil, hashlib, datetime

HOME      = os.path.expanduser("~")
SRC_ROOT  = f"{HOME}/.claude/projects"
STAGE_DIR = f"{HOME}/os-agent/hf-dataset"
TX_DIR    = f"{STAGE_DIR}/transcripts"
REPO      = "crispwisp/wisp-claude-code-sessions"
STATE     = f"{HOME}/.local/share/wisp/trace-publish.state"
LOG       = f"{HOME}/.local/share/wisp/trace-publish.log"

CRED_FILES = [
    f"{HOME}/.local/share/wisp/credentials",
    f"{HOME}/.local/share/wisp/openrouter",
]

# values we deliberately keep — public identifiers
PUBLIC_ALLOW = {"crispwisp", "crispwisp@proton.me", "huggingface.co"}
PUBLIC_HINTS = ("crispwisp", "proton", "github.com", "huggingface", "openrouter.ai")

# canonical secret formats — caught even for brand-new keys
REGEXES = [re.compile(p) for p in [
    r'sk-or-v1-[A-Za-z0-9]{20,}', r'sk-ant-[A-Za-z0-9_-]{20,}', r'sk-[A-Za-z0-9]{40,}',
    r'hf_[A-Za-z0-9]{30,}', r'ghp_[A-Za-z0-9]{20,}', r'github_pat_[A-Za-z0-9_]{20,}',
    r'gho_[A-Za-z0-9]{20,}', r'glpat-[A-Za-z0-9_-]{20,}',
    r'xox[baprs]-[A-Za-z0-9-]{10,}', r'AKIA[0-9A-Z]{16}',
    r'AIza[0-9A-Za-z_-]{30,}', r'-----BEGIN [A-Z ]*PRIVATE KEY-----',
]]
SENSITIVE_KEY = re.compile(r'(pass|passwd|password|secret|token|api[_-]?key|cookie|auth|bearer|session|private)', re.I)
EMAIL_RE  = re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')
DOMAIN_RE = re.compile(r'^[a-z0-9.-]+\.[a-z]{2,}$', re.I)

REDACT = "[REDACTED-SECRET]"


def log(msg):
    ts = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    line = f"{ts} {msg}"
    print(line, flush=True)
    try:
        with open(LOG, "a") as fh:
            fh.write(line + "\n")
    except OSError:
        pass


def is_allowed(v):
    if v in PUBLIC_ALLOW:
        return True
    if EMAIL_RE.match(v) or DOMAIN_RE.match(v):
        return True
    vl = v.lower()
    return any(h in vl for h in PUBLIC_HINTS)


def keylike(v):
    if any(v.startswith(p) for p in ("sk-", "hf_", "ghp_", "gho_", "github_pat_", "glpat-", "xox", "AKIA", "AIza")):
        return True
    has_up = any(c.isupper() for c in v); has_lo = any(c.islower() for c in v)
    has_di = any(c.isdigit() for c in v); has_sp = any(c in "%$!*#&^+/=" for c in v)
    return (has_up and has_lo) or (has_di and (has_up or has_lo)) or has_sp


def collect_secrets():
    """Pull credential VALUES from cred files. Key-named-sensitive values are
    taken verbatim; bare high-entropy lines are taken too. Public IDs excluded."""
    secrets = set()
    for path in CRED_FILES:
        if not os.path.exists(path):
            continue
        raw = open(path, encoding="utf-8", errors="replace").read()
        for ln in raw.splitlines():
            ln = ln.strip()
            if not ln:
                continue
            m = re.match(r'^["\']?([A-Za-z0-9_.\- ]{1,40})["\']?\s*[:=]\s*["\']?(.+?)["\']?,?\s*$', ln)
            if m:
                key, val = m.group(1).strip(), m.group(2).strip()
                if SENSITIVE_KEY.search(key) and len(val) >= 6 and not is_allowed(val):
                    secrets.add(val)
                continue
            # bare token line (e.g. a lone API key)
            if " " not in ln and len(ln) >= 20 and keylike(ln) and not is_allowed(ln):
                secrets.add(ln)
        # also grab any canonical-format token literally present in the cred file
        for rx in REGEXES:
            for hit in rx.findall(raw):
                if not is_allowed(hit):
                    secrets.add(hit)
    return sorted(secrets, key=len, reverse=True)  # longest first


def scrub(data, secrets):
    n = 0
    for s in secrets:
        if s in data:
            n += data.count(s)
            data = data.replace(s, REDACT)
    for rx in REGEXES:
        data, k = rx.subn(REDACT, data)
        n += k
    return data, n


def build_stage(secrets):
    if os.path.exists(TX_DIR):
        shutil.rmtree(TX_DIR)
    os.makedirs(TX_DIR, exist_ok=True)
    files = glob.glob(f"{SRC_ROOT}/**/*.jsonl", recursive=True)
    total = 0
    for src in files:
        rel = os.path.relpath(src, SRC_ROOT)
        dst = os.path.join(TX_DIR, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        data = open(src, encoding="utf-8", errors="replace").read()
        data, n = scrub(data, secrets)
        open(dst, "w", encoding="utf-8").write(data)
        total += n
    return len(files), total


def verify(secrets):
    """Hard gate: abort if ANY secret value or canonical key survives staging."""
    leaks = 0
    for f in glob.glob(f"{TX_DIR}/**/*.jsonl", recursive=True):
        d = open(f, encoding="utf-8", errors="replace").read()
        for s in secrets:
            if s in d:
                leaks += 1; log(f"LEAK value in {f}")
        for rx in REGEXES:
            if rx.search(d):
                leaks += 1; log(f"LEAK {rx.pattern} in {f}")
    return leaks


def stage_digest():
    h = hashlib.sha256()
    for f in sorted(glob.glob(f"{TX_DIR}/**/*.jsonl", recursive=True)):
        h.update(os.path.relpath(f, TX_DIR).encode())
        with open(f, "rb") as fh:
            h.update(fh.read())
    return h.hexdigest()


def hf_token():
    for path in CRED_FILES:
        if os.path.exists(path):
            m = re.search(r'hf_[A-Za-z0-9]{30,}', open(path, encoding="utf-8", errors="replace").read())
            if m:
                return m.group()
    return os.environ.get("HF_TOKEN")


def push():
    from huggingface_hub import HfApi
    api = HfApi(token=hf_token())
    api.create_repo(REPO, repo_type="dataset", exist_ok=True, private=False)
    stamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
    api.upload_folder(
        repo_id=REPO, repo_type="dataset", folder_path=STAGE_DIR,
        commit_message=f"Refresh scrubbed traces {stamp}",
        delete_patterns=["transcripts/**/*.jsonl"],  # mirror local deletions
    )


def main():
    force = "--force" in sys.argv
    secrets = collect_secrets()
    log(f"loaded {len(secrets)} secret value(s) for scrubbing")
    nfiles, nredact = build_stage(secrets)
    log(f"staged {nfiles} transcripts, {nredact} redaction(s)")
    leaks = verify(secrets)
    if leaks:
        log(f"ABORT: {leaks} secret(s) survived scrub — NOT publishing")
        sys.exit(1)
    log("verify: clean (0 secrets remain)")
    digest = stage_digest()
    prev = open(STATE).read().strip() if os.path.exists(STATE) else ""
    if digest == prev and not force:
        log("no changes since last publish — skipping upload")
        return
    log(f"changes detected — uploading to {REPO}")
    push()
    with open(STATE, "w") as fh:
        fh.write(digest)
    log(f"published OK (digest {digest[:12]})")


if __name__ == "__main__":
    main()

